var particles;
var img = []
var n, s, maxR;
var indexImg = 0;


function setup() {
	// createCanvas(windowWidth, windowHeight);
	createCanvas(1000,1000);
		// pixelDensity(2)
	// background("#FFEDDA");
	// background(255, 240, 221);
	// background(0);
	smooth();

	n = 6000;
	// s = 20;
	s = 10;
	maxR = height/2 - height/10;

	particles = [];

	// img.push(loadImage('https://openprocessing.org/sketch/2296619/files/A.jpg'));
	// img.push(loadImage('https://openprocessing.org/sketch/2296619/files/B.jpg'));
	img.push(loadImage('https://openprocessing.org/sketch/2296619/files/C.jpg'));
	// img.push(loadImage('https://openprocessing.org/sketch/2296619/files/D.jpg'));

}

function draw() {
	// background(0,100);
	translate(width/2, height/2);
	// rotate(frameCount/1000+sin(frameCount%100))//Version2
	rotate(frameCount/50000/sin(10))//Version3
	noStroke();
	// addNoise()
	// blendMode(LIGHTEST)
	// blendMode(MULTIPLY)

	if(s > 1) {
		if(particles.length != 0) {
			for(let i = 0; i < particles.length; i++) {
				var p = particles[i];
				p.show();
				p.move();

				if(p.isDead()) particles.splice(i, 1);
			}
		} else {
			s -= 2;
			initParticles();
		}
	}
}

function initParticles() {	
	for(let i = 0; i < n; i++) {
		particles.push(new Particle(maxR, s));

		var p = particles[i];
		var x = int(map(p.pos.x, -maxR, maxR, 0, img[indexImg].width));
    var y = int(map(p.pos.y, -maxR, maxR, 0, img[indexImg].height));
		p.c = img[indexImg].get(x, y);
	}
}

// function mousePressed() {
