// 	setup();
// }

class Particle {

  constructor(maxR_, s_) {
    this.s = s_;
    this.c = "";
    this.maxR = maxR_;

    // this.life = 100;
		this.life = 5000;

    this.init();
  }

  init() {
    this.pos = p5.Vector.random2D();
    this.pos.normalize();
    this.pos.mult(random(2, maxR));

    this.vel = createVector();
  }

  show() {
    fill(this.c);
    ellipse(this.pos.x, this.pos.y, random(this.s/4),random(this.s/4));
		 // rect(this.pos.x, this.pos.y, this.s, this.s);
    this.life -= 1;
  }

  move() {
    // var angle = noise(this.pos.x / 400, this.pos.y / 400) * TAU;
		var angle = noise(this.pos.x / 50, this.pos.y / 50) * TAU;
    var fc = frameCount/int(random(100,1000))

    this.vel.set(cos(angle)/fc*0.125, sin(angle)/fc*0.2);
    this.vel.mult(0.3);
    this.pos.add(this.vel);
  }


  isDead() {
    var d = dist(random(this.pos.x), random(this.pos.y), random(100,800), random(100,800));

    if(d > this.maxR+1000 || this.life < 1) return true;
    else return false;
  }
}



function keyTyped() {
  if (key === "s" || key === "S") {
    noLoop();
    saveCanvas("Img-001", "png");
  }
}

